const ACTION_RULE = 'Format each as "Owner: task (due date)". Include tasks assigned to ANY participant, not only me. Include every task that has an owner even when no deadline was mentioned — write "(no date given)" instead of a date. Never invent a date.';
const sectionList = modeNoteSections
