        const desc = s.description?.trim() ?? '';
        const full = ACTION_SECTION_RE.test(s.title)
            ? `${desc ? desc + ' ' : ''}${ACTION_RULE}`
            : desc;
        return full ? `- "${s.title}": ${full}` : `- "${s.title}"`;
    })
    .join('\n');

